import {scenarios,sourceLinks,stanceOf,seriesFor} from './data.js';

const $=s=>document.querySelector(s);
const main=$('#main'),dialog=$('#sheet');
let state={scenario:'hawk',page:'overview',period:30,filter:'all',memberFilter:'all',meeting:'next'};
let lastFocus;
const icons={arrow:'<path d="m7 4 8 8-8 8"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',spark:'<path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4z"/>',trend:'<path d="m3 17 6-6 4 4 8-10M15 5h6v6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',quiet:'<path d="M9 4h2v16H9zM15 4h2v16h-2z"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg>`;
const sign=x=>x>0?`+${x}`:`${x===0?'±0':x}`;
const cls=x=>x>0?'up':x<0?'down':'flat';
const active=(a,b)=>a===b?'active':'';
const escaped=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function polar(angle,r=132){const rad=angle*Math.PI/180;return [168+Math.cos(rad)*r,154-Math.sin(rad)*r]}
function arc(from,to){const a=polar(from),b=polar(to);return `M${a.join(' ')} A132 132 0 0 1 ${b.join(' ')}`}
function gauge(d){
 const colors=['#69bda6','#a2d5b6','#e6dba0','#ebbb79','#df9265'];
 const needle=polar(180-d.score*1.8,132);
 return `<div class="gauge"><svg viewBox="0 0 336 207" role="img" aria-label="鹰鸽指数 ${d.score}，${d.label}，0 为最鸽，100 为最鹰"><path d="${arc(180,0)}" stroke="#f0f3f5" stroke-width="18" fill="none"/>${colors.map((c,i)=>`<path d="${arc(180-i*36-1,180-(i+1)*36+1)}" stroke="${c}" stroke-width="18" fill="none"/>`).join('')}<path d="${arc(180,0)}" stroke="#fff" stroke-width="2" fill="none" stroke-dasharray="1 16" opacity=".7"/><circle cx="${needle[0]}" cy="${needle[1]}" r="10" fill="white" stroke="${d.color}" stroke-width="3"/><circle cx="${needle[0]}" cy="${needle[1]}" r="3" fill="${d.color}"/><text x="13" y="179" font-size="9" fill="#a0abb4">0</text><text x="162" y="4" font-size="9" fill="#a0abb4">50</text><text x="306" y="179" font-size="9" fill="#a0abb4">100</text></svg><div class="gauge-value"><div class="score">${d.score}</div><div class="score-sub">FED SENTIMENT INDEX</div><span class="stance" style="color:${d.color};background:${d.soft}">${d.label}</span></div><div class="gauge-labels"><span>鸽派 · 宽松</span><span>中性</span><span>鹰派 · 收紧</span></div></div>`;
}
function signalRows(signals){
 if(!signals.length)return `<div class="empty-state">${icon('quiet')}今日无新增有效政策信号<br><span style="font-size:10px">主指数沿用 10.09 的最近有效读数</span></div>`;
 return signals.map(s=>{const index=scenarios[state.scenario].signals.indexOf(s);return `<button class="signal" data-signal="${index}" aria-label="查看${s.name}：${s.title}"><span class="avatar ${s.impact<0?'teal':s.impact===0?'gray':''}">${s.initial}</span><span class="signal-main"><span class="signal-name">${s.name}</span><span class="signal-title">${s.title}</span><span class="signal-time">${s.time} · ${s.role}</span></span><span class="impact ${cls(s.impact)}">${sign(s.impact)}<small>指数贡献</small></span></button>`}).join('');
}
function chart(d){
 const points=seriesFor(state.scenario,state.period);const x=i=>10+i/(points.length-1)*289,y=s=>105-s*.85;
 const path=points.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(2)},${y(p.score).toFixed(2)}`).join(' ');
 const last=points.at(-1);
 return `<div class="chart-card"><div class="chart-head"><div class="legend"><i style="background:${d.color}"></i>沟通指数</div><div class="segments" aria-label="走势时间范围">${[7,30,90].map(n=>`<button data-period="${n}" class="${active(n,state.period)}" aria-pressed="${n===state.period}">${n}天</button>`).join('')}</div></div><div class="chart-wrap"><svg class="chart-svg" id="trend-chart" viewBox="0 0 340 128" role="img" aria-label="最近${state.period}天模拟走势，最新${d.score}"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${d.color}" stop-opacity=".18"/><stop offset="100%" stop-color="${d.color}" stop-opacity="0"/></linearGradient></defs>${[25,50,75].map(v=>`<line x1="10" y1="${y(v)}" x2="305" y2="${y(v)}" stroke="${v===50?'#dce4e9':'#f0f3f6'}" stroke-dasharray="${v===50?'4 4':'0'}"/><text x="316" y="${y(v)+3}" font-size="8" fill="#a2acb4">${v}</text>`).join('')}<path d="${path} L299,112 L10,112 Z" fill="url(#chart-fill)"/><path d="${path}" stroke="${d.color}" stroke-width="2.1" fill="none" stroke-linejoin="round"/><circle cx="299" cy="${y(last.score)}" r="5" fill="${d.color}" fill-opacity=".13"/><circle cx="299" cy="${y(last.score)}" r="2.6" fill="${d.color}"/><line id="chart-cursor" x1="299" y1="16" x2="299" y2="112" stroke="#8a9aa9" stroke-dasharray="3 3" visibility="hidden"/></svg></div><div class="chart-note"><span>${points[0].date.slice(5).replace('-','.')}</span><span>虚线 = 中性 50</span><span>10.12</span></div><div class="chart-readout" id="chart-readout">滑动查看历史读数 · 模拟数据</div><input type="range" min="0" max="${points.length-1}" value="${points.length-1}" id="chart-range" aria-label="选择历史日期" style="position:absolute;width:1px;height:1px;opacity:0"></div>`;
}
function market(d){const probs=state.meeting==='next'?d.market:d.nextMarket;return `<div class="market-card"><div class="market-top"><div class="market-title">${state.meeting==='next'?'下一次':'随后一次'}降息概率</div><select class="meeting-select" id="meeting-select" aria-label="选择模拟会议"><option value="next" ${state.meeting==='next'?'selected':''}>下次会议</option><option value="later" ${state.meeting==='later'?'selected':''}>随后一次会议</option></select></div><div class="market-value">${probs[0]}<span style="font-size:17px">%</span><small>降息 25bp · 模拟概率</small></div><div class="prob-bar" aria-label="降息${probs[0]}%，维持${probs[1]}%，加息${probs[2]}%"><span style="width:${probs[0]}%;background:#75bbaa"></span><span style="width:${probs[1]}%;background:#cdd5dd"></span><span style="width:${probs[2]}%;background:#e9b58f"></span></div><div class="prob-legend"><span><i style="background:#75bbaa"></i>降息 ${probs[0]}%</span><span><i style="background:#cdd5dd"></i>维持 ${probs[1]}%</span><span><i style="background:#e9b58f"></i>加息 ${probs[2]}%</span></div><div class="market-insight">${icon('info')}<span><b>${state.meeting==='next'?d.gap:'此为随后一次会议的独立概率示例。'}</b><br>与主指数独立展示 · 参考 FedWatch 产品逻辑</span></div></div>`}
function overview(d){return `<div class="content page-enter"><div class="eyebrow">THE FED, AT A GLANCE</div><div class="title-row"><h1>美联储鹰鸽指数</h1><button class="text-button" data-open="explain" aria-label="了解指数">${icon('info')}</button></div><div class="date">2026 年 10 月 12 日，周一 · 北京时间</div><section class="hero" aria-label="当前沟通指数"><div class="hero-top"><span>政策沟通立场</span><span class="status ${state.scenario==='quiet'?'quiet':''}">${d.status}</span></div>${gauge(d)}<div class="stats"><div class="stat"><span class="label">较前次更新</span><strong class="${cls(d.score-d.previous)}">${sign(d.score-d.previous)}<small> 点</small></strong></div><div class="stat"><span class="label">近 7 日变化</span><strong class="${cls(d.score-d.week)}">${sign(d.score-d.week)}<small> 点</small></strong></div><div class="stat"><span class="label">最近有效更新</span><strong style="font-size:16px;margin-top:10px">${d.update.split(' ')[0]} <small>${d.update.split(' ')[1]}</small></strong></div></div></section><div class="insight">${icon('spark')}<span><b>${d.summary}</b><br>${d.description}</span></div><div class="section-heading"><h2>立场如何变化</h2><button class="text-button" data-open="history">历史读数 ${icon('arrow')}</button></div>${chart(d)}<div class="section-heading"><h2>市场在想什么</h2><span class="legend">独立参考</span></div>${market(d)}<div class="section-heading"><h2>${state.scenario==='quiet'?'最新政策信号':'什么推动了变化'}</h2><a class="text-button" href="#signals">全部信号 ${icon('arrow')}</a></div><div class="signals-list">${signalRows(d.signals.slice(0,3))}</div><p class="footnote">演示数据 · 分数、概率、委员与讲话均为虚构示例<br>政策沟通指数不等同于实际利率或加降息概率</p></div>`}
function signals(d){const list=d.signals.filter(s=>state.filter==='all'||(state.filter==='hawk'?s.impact>0:s.impact<0));return `<div class="content page-enter"><div class="eyebrow">FOLLOW THE EVIDENCE</div><h1>政策信号</h1><p class="subheading">每一次变化，都有迹可循。</p><div class="page-card"><div class="row"><span style="font-size:12px">${state.scenario==='quiet'?'今日暂无变化':'本次更新的归因'}</span><strong class="${cls(d.score-d.previous)}" style="font-size:25px">${sign(d.score-d.previous)}<small style="font-size:11px"> 点</small></strong></div><p>${d.previous} → ${d.score} · 讲话贡献与时间权重变化之和</p></div><div class="filter-row" aria-label="信号方向筛选">${[['all','全部'],['hawk','偏鹰信号'],['dove','偏鸽信号']].map(([v,n])=>`<button data-filter="${v}" class="${active(v,state.filter)}" aria-pressed="${v===state.filter}">${n}</button>`).join('')}</div><div class="signals-list">${list.length?signalRows(list):state.scenario==='quiet'?signalRows([]):'<div class="empty-state">该场景下没有此类信号。</div>'}</div><div class="muted-banner">这里展示的是模拟归因。实际产品须保存原始文本、来源链接、发布日期、评分依据和模型版本；每条贡献应由重算差值确定。</div><button class="download" id="download">${icon('download')}导出本场景模拟数据</button><p class="footnote">示例讲话并非真实官员引述</p></div>`}
function committee(d){const counts=[d.members.filter(s=>s<45).length,d.members.filter(s=>s>=45&&s<=55).length,d.members.filter(s=>s>55).length];const names=['理事 A','地区联储主席 B','理事 D','理事 E','地区联储主席 F','理事 C'];const members=d.members.map((s,i)=>({score:s,name:names[i],index:i})).filter(m=>state.memberFilter==='all'||m.index!==4);const spread=Math.max(...d.members)-Math.min(...d.members);return `<div class="content page-enter"><div class="eyebrow">INSIDE THE COMMITTEE</div><h1>委员立场</h1><p class="subheading">平均分之外，看见意见的分布。</p><div class="page-card"><div class="row"><h2>6 位示例委员</h2><span class="legend">未加权人数分布</span></div><div class="distribution"><span style="width:${counts[0]/6*100}%;background:#79baa7"></span><span style="width:${counts[1]/6*100}%;background:#cbd4dc"></span><span style="width:${counts[2]/6*100}%;background:#e2a474"></span></div><div class="distribution-legend"><span>偏鸽 ${counts[0]} 人</span><span>中性 ${counts[1]} 人</span><span>偏鹰 ${counts[2]} 人</span></div><div class="insight" style="margin-top:17px">${icon('info')}<span>示例委员最高与最低分相差 <b>${spread} 点</b>。<br>分歧程度与委员会平均分需同时观察。</span></div></div><div class="filter-row">${[['all','全部委员'],['voters','示例投票委员']].map(([v,n])=>`<button class="${active(v,state.memberFilter)}" data-member-filter="${v}" aria-pressed="${v===state.memberFilter}">${n}</button>`).join('')}</div><div class="page-card" style="margin-top:0;padding-top:0;padding-bottom:0">${members.map(m=>`<div class="member"><span class="avatar ${m.score<45?'teal':m.score<=55?'gray':''}">${m.name.at(-1)}</span><div class="member-info"><div class="member-name">${m.name}</div><div class="member-role">${m.index===4?'示例非投票委员':'示例投票委员'} · 90 日沟通窗口</div><div class="mini-bar"><span style="width:${m.score}%;background:${m.score<45?'#79baa7':m.score<=55?'#cbd4dc':'#e2a474'}"></span></div></div><div class="member-score" style="color:${m.score<45?'#389b88':m.score<=55?'#8793a4':'#ce8150'}">${m.score}<small>${stanceOf(m.score)}</small></div></div>`).join('')}</div><p class="footnote">委员身份与读数仅为演示，不代表现任成员<br>此分布与主指数是独立演示样本，不直接取平均</p></div>`}
function method(){return `<div class="content page-enter"><div class="eyebrow">A NUMBER YOU CAN UNDERSTAND</div><h1>读懂这个指数</h1><p class="subheading">让复杂的政策沟通，变得清晰。</p><div class="page-card"><h2>0 最鸽，100 最鹰</h2><p>50 是固定中性点。高分表示更倾向收紧或维持限制，低分表示更倾向宽松。45–55 是中性观察区间。</p><div class="method-scale">${['#69bda6','#a2d5b6','#e6dba0','#ebbb79','#df9265'].map(c=>`<span style="background:${c}"></span>`).join('')}</div><div class="method-labels"><span>0 · 明显鸽派</span><span>50 · 中性</span><span>100 · 明显鹰派</span></div><p>这是沟通立场，不是实际政策限制程度，也不是加降息概率。</p></div><div class="page-card"><h2>我们选择的方案</h2><p>结合 FXStreet 的事件更新、RoboMacro 的可解释计算和证据追溯，市场预期独立展示。以下参数为拟定的 v1 方案，尚未完成历史校准。</p>${[['官方证据优先','采集理事会及地区联储官网的政策讲话。声明、纪要及发布会作为会议信号独立展示；重复转载只计一次。'],['先给讲话评分，再汇总到人','单篇用固定规则评为 −1 至 +1；按政策相关性、置信度与时间衰减加权。先按委员聚合，避免发言多的人天然占据更大权重。'],['汇总委员会立场','90 日窗口，时间权重 e^(−天数/30)。角色权重拟设主席 2、副主席 1.5、其他 1；当年投票委员乘 1.25，须核实官方身份。'],['每日查看，有效事件触发更新','新增有效讲话或数据修正时重算。无新信号时沿用读数并保留有效更新时间；覆盖率与数据陈旧程度每日检查。']].map(([h,p],i)=>`<div class="method-step"><span class="step-no">0${i+1}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}<div class="formula">委员得分 m = Σ(讲话分 × 权重) / Σ权重<br>综合立场 S = Σ(委员分 × 角色权重) / Σ角色权重<br><b>鹰鸽指数 I = 50 × (1 + S)</b></div><p>缺失样本不按中性填充；低置信样本人工复核。覆盖不足时只报告已覆盖委员，并降低可信度。模型版本、历史修正和更新日志需留存。</p></div><div class="page-card"><h2>市场已经有哪些产品</h2><p>核查日期：2026.10.12。下列为产品与方法参考；本 demo 没有接入其数据，也没有复制其最新读数。</p>${sourceLinks.map(s=>`<a class="research-row" href="${s.url}" target="_blank" rel="noopener noreferrer"><div class="row"><b>${s.name} ↗</b><span>${s.kind}</span></div><p>${s.text}</p></a>`).join('')}</div><div class="page-card"><h2>从 demo 到正式产品</h2><p>下一步应接入官方文本采集，建立带日期的真实委员名单与投票权，保存人工标注集，验证历史稳定性与事件归因；市场概率需使用有授权的数据接口。</p><p>本页所有读数、历史曲线、讲话和委员均为模拟数据。未接入实时行情，不代表美联储当前实际立场。</p></div><button class="download" id="download">${icon('download')}下载模拟历史数据 CSV</button><p class="footnote">FED PULSE · PRODUCT CONCEPT v1.0</p></div>`}
function render(){const d=scenarios[state.scenario];main.innerHTML=({overview:()=>overview(d),signals:()=>signals(d),committee:()=>committee(d),method})[state.page]();document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===state.page);if(a.dataset.page===state.page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});bindChart()}
function showSheet(title,body){lastFocus=document.activeElement;$('#sheet-title').textContent=title;$('#sheet-content').innerHTML=body;if(!dialog.open)dialog.showModal();}
function closeSheet(){dialog.close();lastFocus?.focus()}
function scenarioSheet(){showSheet('切换演示场景',`<p class="sheet-description">体验同一产品在不同政策环境下的表现。所有数值与讲话都是模拟数据。</p>${[['hawk','偏鹰升温','收紧倾向增强，追溯 +6 点变化'],['dove','转向偏鸽','宽松倾向增强，市场同步变化'],['neutral','中性观望','鹰鸽信号相互抵消'],['quiet','静默 / 无新增信号','保留有效读数，独立更新市场预期']].map(([key,title,desc])=>`<button class="scenario-option ${state.scenario===key?'selected':''}" data-scenario="${key}"><span class="scenario-number" style="color:${scenarios[key].color}">${scenarios[key].score}</span><span><strong>${title}</strong><small>${desc}</small></span><span class="scenario-check">${state.scenario===key?'✓':'›'}</span></button>`).join('')}<p class="sheet-caption">静默场景用于演示更新规则，并非对当前真实静默期的判断。</p>`)}
function details(index){const s=scenarios[state.scenario].signals[index];if(!s)return;showSheet(s.name,`<div class="row"><span class="stance" style="background:${s.impact<0?'#eaf6f1':'#fff1e5'};color:${s.impact<0?'#389b88':'#b87a50'}">${s.score===null?'计算项':stanceOf(s.score)}</span><span class="legend">模拟事件 · 10.12 ${s.time}</span></div><div class="sheet-quote">${escaped(s.quote)}</div><p class="sheet-caption">${s.score===null?'模型规则示例':'示例讲话 · 虚构内容，非真实官员引述'}</p><div class="detail-grid"><div>本次指数贡献<strong class="${cls(s.impact)}">${sign(s.impact)} 点</strong></div><div>${s.score===null?'计算类型':'单篇讲话评分'}<strong>${s.score===null?'时间权重':s.score+' / 100'}</strong></div></div><h3>为什么这样评分</h3><p class="sheet-body" style="margin-top:8px">${s.reason}</p><p class="sheet-caption">指数贡献与单篇分数是不同概念：贡献表示相对前次更新的变化。生产版应提供原文链接与精确重算记录；该虚构示例没有原文链接。</p>`)}
function historySheet(){const p=seriesFor(state.scenario,state.period);showSheet('历史读数 · 模拟数据',`<p class="sheet-description">最近 ${state.period} 天的演示序列。数值仅用于测试走势交互。</p><div style="max-height:45vh;overflow:auto">${p.slice().reverse().map(i=>`<div class="row" style="padding:12px 0;border-bottom:1px solid #edf1f4;font-size:12px"><span>${i.date}</span><strong>${i.score} <span style="font-size:10px;font-weight:400;color:#8c99a4">${stanceOf(i.score)}</span></strong></div>`).join('')}</div><button class="download" id="download">${icon('download')}导出 CSV</button>`)}
function explain(){showSheet('一眼读懂鹰鸽',`<p class="sheet-body">鹰派更关注通胀，倾向提高利率或保持限制性政策；鸽派更关注就业与增长风险，倾向降低政策限制程度。</p><div class="page-card"><h3>为什么是 ${scenarios[state.scenario].score} 分？</h3><p>当前为${scenarios[state.scenario].label}场景的固定示例值。正式产品将先聚合每位委员的政策语言，再按角色与投票权汇总为 0–100 分。</p></div><div class="page-card"><h3>分数高，会加息吗？</h3><p>分数反映公开沟通倾向，不直接预测下一次利率决议。市场预期模块显示的是另一个维度。</p></div><button class="download" data-go-method>查看完整方法与参考来源 ${icon('arrow')}</button>`)}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2400)}
function download(){const rows=seriesFor(state.scenario,state.period);const csv='\ufeffdate,simulated_fed_communication_index,scenario,data_status\r\n'+rows.map(r=>`${r.date},${r.score},${state.scenario},SIMULATED_NOT_LIVE`).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`fed-pulse-SIMULATED-${state.scenario}-${state.period}d.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('模拟数据 CSV 已导出')}
function bindChart(){const svg=$('#trend-chart');if(!svg)return;const points=seriesFor(state.scenario,state.period);const read=i=>{const p=points[i];$('#chart-readout').textContent=`${p.date.replaceAll('-','.')} · ${p.score} 分 · ${stanceOf(p.score)}（模拟）`;const x=10+i/(points.length-1)*289;$('#chart-cursor').setAttribute('x1',x);$('#chart-cursor').setAttribute('x2',x);$('#chart-cursor').setAttribute('visibility','visible')};svg.addEventListener('pointermove',e=>{const b=svg.getBoundingClientRect();const ratio=((e.clientX-b.left)/b.width*340-10)/289;read(Math.max(0,Math.min(points.length-1,Math.round(ratio*(points.length-1)))))});svg.addEventListener('pointerleave',()=>$('#chart-cursor').setAttribute('visibility','hidden'));$('#chart-range').addEventListener('input',e=>read(Number(e.target.value)));}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='scenario-button')scenarioSheet();if(b.id==='close-sheet')closeSheet();if(b.dataset.scenario){state.scenario=b.dataset.scenario;state.filter='all';render();closeSheet();toast('已切换到'+({hawk:'偏鹰',dove:'偏鸽',neutral:'中性',quiet:'静默'}[state.scenario])+'演示场景')}if(b.dataset.period){state.period=Number(b.dataset.period);render()}if(b.dataset.filter){state.filter=b.dataset.filter;render()}if(b.dataset.memberFilter){state.memberFilter=b.dataset.memberFilter;render()}if(b.dataset.signal!==undefined)details(Number(b.dataset.signal));if(b.dataset.open==='history')historySheet();if(b.dataset.open==='explain')explain();if(b.hasAttribute('data-go-method')){closeSheet();location.hash='method'}if(b.id==='download')download()});
document.addEventListener('change',e=>{if(e.target.id==='meeting-select'){state.meeting=e.target.value;render()}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet()}});
dialog.addEventListener('cancel',()=>lastFocus?.focus());
function navigate(){const p=location.hash.slice(1);state.page=['overview','signals','committee','method'].includes(p)?p:'overview';render();window.scrollTo(0,0)}
window.addEventListener('hashchange',navigate);navigate();
